class Solution {
public:
    int maxRepOpt1(string text) {
        int freq[26] = {0};
        for(char c : text) freq[c - 'a']++;

        int ans = 0, n = text.size();
        for(int i = 0; i < n; i++) {
            int j = i, diff = 0, cnt = 0;
            while(j < n && (text[j] == text[i] || diff == 0) && cnt < freq[text[i] - 'a']){
                if(text[j] != text[i]) diff++;
                cnt++;
                j++;
            }
            if(cnt < freq[text[i] - 'a'] && diff == 0) cnt++;
            ans = max(ans, cnt);
        }
        return ans;
    }
};
